/**
* Generate Boost test fixtures.
*
* ## Notes
*
* -   Run this script from the directory in which fixtures should be written.
* -   Follows the test data generation patterns from Boost's ibeta_data.cpp
*     (see https://github.com/boostorg/math/blob/develop/tools/ibeta_data.cpp).
*     Reference values are computed via Boost library functions, which
*     internally promote double to long double (80-bit extended on x86),
*     providing slightly higher precision than double for reference data.
*
* ## Fixture Categories (matching Boost's test_ibeta.hpp)
*
* 1. output.json             - Medium a,b in [1,40] (original fixture)
* 2. small_range.json        - Small a,b in [0,10] (ibeta_small_data style)
* 3. medium_range.json       - Medium a,b in [0,100] (ibeta_data style)
* 4. large_range.json        - Large range a,b ~ 10^-5 to 10^6 (ibeta_large_data style)
* 5. int_values.json         - Integer a,b in {1,5,9,...,37} (ibeta_int_data style)
*
*/
#include <stdlib.h>
#include <stdio.h>
#include <cmath>
#include <boost/random/mersenne_twister.hpp>
#include <boost/random/uniform_int_distribution.hpp>
#include <boost/random/uniform_real_distribution.hpp>
#include <boost/math/special_functions/beta.hpp>

using boost::random::uniform_real_distribution;
using boost::random::uniform_int_distribution;
using boost::random::mt19937;

// Define a new pseudorandom number generator:
mt19937 rng;

/**
* Generates a linearly spaced numeric array of doubles.
*
* ## Notes
*
* -   Assumes that the output array has at least 2 elements.
* -   Output array is guaranteed to include both the start and end values.
*
*
* @param out    output array
* @param len    array length
* @param start  first value
* @param end    last value
*/
void linspace_f64( double *out, const unsigned int len, const double start, const double end ) {
	unsigned int i;
	double incr;

	incr = (end-start) / (len-1);
	for ( i = 0; i < len-1; i++ ) {
		out[ i ] = start + (incr*i);
	}
	out[ i ] = end;
}

/**
* Generates a linearly spaced numeric array of integers.
*
* ## Notes
*
* -   Assumes that the output array has at least 2 elements.
* -   Output array is guaranteed to include both the start and end values.
*
*
* @param out    output array
* @param len    array length
* @param start  first value
* @param end    last value
*/
void linspace_i32( int *out, const unsigned int len, const int start, const int end ) {
	unsigned int i;
	int incr;

	incr = (end-start) / (len-1);
	for ( i = 0; i < len-1; i++ ) {
		out[ i ] = start + (incr*i);
	}
	out[ i ] = end;
}

/**
* Generates an array of pseudorandom doubles drawn from a uniform distribution.
*
* @param out  output array
* @param len  array length
* @param a    lower bound (inclusive)
* @param b    upper bound (exclusive)
*/
void rand_array_f64( double *out, const unsigned int len, const double a, const double b ) {
	unsigned int i;

	// Define a uniform distribution for generating pseudorandom numbers:
	uniform_real_distribution<> randu( a, b );

	for ( i = 0; i < len; i++ ) {
		out[ i ] = randu( rng );
	}
}

/**
* Generates an array of pseudorandom integers drawn from a uniform distribution.
*
* @param out  output array
* @param len  array length
* @param a    lower bound (inclusive)
* @param b    upper bound (exclusive)
*/
void rand_array_i32( int *out, const unsigned int len, const int a, const int b ) {
	unsigned int i;

	// Define a uniform distribution for generating pseudorandom numbers:
	uniform_int_distribution<> randi( a, b );

	for ( i = 0; i < len; i++ ) {
		out[ i ] = randi( rng );
	}
}

/**
* Casts an array of integers to an array of doubles.
*
* @param out  output array
* @param x    input array
* @param len  array length
*/
void i32_to_f64( double *out, int *x, unsigned int len ) {
	unsigned int i;

	for ( i = 0; i < len; i++ ) {
		out[ i ] = (double) x[ i ];
	}
}

/**
* Casts an array of doubles to an array of integers.
*
* @param out  output array
* @param x    input array
* @param len  array length
*/
void f64_to_i32( int *out, double *x, unsigned int len ) {
	unsigned int i;

	for ( i = 0; i < len; i++ ) {
		out[ i ] = (int) x[ i ];
	}
}

/**
* Writes an array of doubles to a file as a series of comma-separated values.
*
* @param f    file to write to
* @param x    array of doubles
* @param len  array length
*/
void write_array_f64( FILE *f, const double *x, const unsigned int len ) {
	unsigned int i;
	for ( i = 0; i < len; i++ ) {
		fprintf( f, "%.17g", x[ i ] );
		if ( i < len-1 ) {
			fprintf( f, "," );
		}
	}
}

/**
* Writes an array of integers to a file as a series of comma-separated values.
*
* @param f    file to write to
* @param x    array of integers
* @param len  array length
*/
void write_array_i32( FILE *f, const int *x, const unsigned int len ) {
	unsigned int i;

	for ( i = 0; i < len; i++ ) {
		fprintf( f, "%d", x[ i ] );
		if ( i < len-1 ) {
			fprintf( f, "," );
		}
	}
}

/**
* Writes a named array of doubles to a file as JSON.
*
* @param f     file to write to
* @param name  array name
* @param x     data
* @param len   array length
*/
void write_named_array_f64( FILE *f, const char *name, const double *x, const unsigned int len ) {
	fprintf( f, "\"%s\":[", name );
	write_array_f64( f, x, len );
	fprintf( f, "]" );
}

/**
* Writes a named array of integers to a file as JSON.
*
* @param f     file to write to
* @param name  array name
* @param x     data
* @param len   array length
*/
void write_named_array_i32( FILE *f, const char *name, const int *x, const unsigned int len ) {
	fprintf( f, "\"%s\":[", name );
	write_array_i32( f, x, len );
	fprintf( f, "]" );
}

/**
* Writes data to a file as JSON.
*
* ## Notes
*
* -   This function SHOULD be tailored to the input data (e.g., input types, output types, number of arguments, etc) and may vary from use case to use case.
*
*
* @param f                    file to write to
* @param x                    first parameter
* @param a                    second parameter
* @param b                    third parameter
* @param lower_regularized    lower regularized incomplete beta function
* @param upper_regularized    upper regularized incomplete beta function
* @param lower_unregularized  lower unregularized incomplete beta function
* @param upper_unregularized  upper unregularized incomplete beta function
* @param derivative_regularized  derivative regularized incomplete beta function
* @param derivative_unregularized  derivative unregularized incomplete beta function
* @param len                  array length
*/
void write_data_as_json(
	FILE *f,
	const double *x,
	const double *a,
	const double *b,
	const double *lower_regularized,
	const double *upper_regularized,
	const double *lower_unregularized,
	const double *upper_unregularized,
	const double *derivative_regularized,
	const double *derivative_unregularized,
	const unsigned int len
) {
	fprintf( f, "{" );
	write_named_array_f64( f, "x", x, len );
	fprintf( f, "," );
	write_named_array_f64( f, "a", a, len );
	fprintf( f, "," );
	write_named_array_f64( f, "b", b, len );
	fprintf( f, "," );
	write_named_array_f64( f, "lower_regularized", lower_regularized, len );
	fprintf( f, "," );
	write_named_array_f64( f, "upper_regularized", upper_regularized, len );
	fprintf( f, "," );
	write_named_array_f64( f, "lower_unregularized", lower_unregularized, len );
	fprintf( f, "," );
	write_named_array_f64( f, "upper_unregularized", upper_unregularized, len );
	fprintf( f, "," );
	write_named_array_f64( f, "derivative_regularized", derivative_regularized, len );
	fprintf( f, "," );
	write_named_array_f64( f, "derivative_unregularized", derivative_unregularized, len );
	fprintf( f, "}" );
}

/**
* Generates test fixtures.
*
* @param x     first parameter
* @param a     second parameter
* @param b     third parameter
* @param len   number of values in the domain
* @param name  output filename
*/
void generate( double *x, double *a, double *b, const unsigned int len, const char *name ) {
	double *upper_unregularized;
	double *lower_unregularized;
	double *upper_regularized;
	double *lower_regularized;
	double *derivative_regularized;
	double *derivative_unregularized;
	unsigned int i;
	FILE *f;

	// Allocate an output array:
	lower_regularized = (double*) malloc( len * sizeof(double) );
	if ( lower_regularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}
	upper_regularized = (double*) malloc( len * sizeof(double) );
	if ( upper_regularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}
	lower_unregularized = (double*) malloc( len * sizeof(double) );
	if ( lower_unregularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}
	upper_unregularized = (double*) malloc( len * sizeof(double) );
	if ( upper_unregularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}
	derivative_regularized = (double*) malloc( len * sizeof(double) );
	if ( derivative_regularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}
	derivative_unregularized = (double*) malloc( len * sizeof(double) );
	if ( derivative_unregularized == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	// Generate fixture data:
	for ( i = 0; i < len; i++ ) {
		double arg1 = a[ i ];
		double arg2 = b[ i ];
		double arg3 = x[ i ];
		lower_regularized[ i ] = boost::math::ibeta( arg1, arg2, arg3 );
		upper_regularized[ i ] = boost::math::ibetac( arg1, arg2, arg3 );
		lower_unregularized[ i ] = boost::math::beta( arg1, arg2, arg3 );
		upper_unregularized[ i ] = boost::math::betac( arg1, arg2, arg3 );
		derivative_regularized[ i ] = boost::math::ibeta_derivative( arg1, arg2, arg3 );
		// NOTE: `kernel-betainc` currently returns the regularized derivative
		derivative_unregularized[ i ] = derivative_regularized[ i ];
	}
	// Open a new file:
	f = fopen( name, "w" );
	if ( f == NULL ) {
		printf( "Error opening file.\n" );
		exit( 1 );
	}
	// Write data as JSON:
	write_data_as_json( f, x, a, b, lower_regularized, upper_regularized, lower_unregularized, upper_unregularized, derivative_regularized, derivative_unregularized, len );

	// Close the file:
	fclose( f );

	// Free allocated memory:
	free( lower_regularized );
	free( upper_regularized );
	free( lower_unregularized );
	free( upper_unregularized );
	free( derivative_regularized );
	free( derivative_unregularized );
}

/**
* Generates "small a,b" fixture (ibeta_small_data style).
*
* Following Boost's beta_data_generator_small: a,b = U[0,100]/10 giving
* a,b in [0, 10], with random x in (0.0001, 1).
*
* @param name  output filename
*/
void generate_small( const char *name ) {
	unsigned int len = 500;
	double *x;
	double *a;
	double *b;
	unsigned int i;

	uniform_real_distribution<> rand_x( 0.0001, 1.0 );
	uniform_real_distribution<> rand_ab( 0.0, 100.0 );

	x = (double*) malloc( len * sizeof(double) );
	a = (double*) malloc( len * sizeof(double) );
	b = (double*) malloc( len * sizeof(double) );
	if ( x == NULL || a == NULL || b == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	for ( i = 0; i < len; i++ ) {
		a[ i ] = rand_ab( rng ) / 10.0;
		b[ i ] = rand_ab( rng ) / 10.0;
		x[ i ] = rand_x( rng );

		// Ensure a,b > 0:
		if ( a[ i ] <= 0.0 ) {
			a[ i ] = 0.001;
		}
		if ( b[ i ] <= 0.0 ) {
			b[ i ] = 0.001;
		}
	}

	generate( x, a, b, len, name );
	free( x );
	free( a );
	free( b );
}

/**
* Generates "medium a,b" fixture (ibeta_data style).
*
* Following Boost's beta_data_generator_medium: a,b = U[0,100], with
* random x in (0.0001, 1).
*
* @param name  output filename
*/
void generate_medium( const char *name ) {
	unsigned int len = 500;
	double *x;
	double *a;
	double *b;
	unsigned int i;

	uniform_real_distribution<> rand_x( 0.0001, 1.0 );
	uniform_real_distribution<> rand_ab( 0.0, 100.0 );

	x = (double*) malloc( len * sizeof(double) );
	a = (double*) malloc( len * sizeof(double) );
	b = (double*) malloc( len * sizeof(double) );
	if ( x == NULL || a == NULL || b == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	for ( i = 0; i < len; i++ ) {
		a[ i ] = rand_ab( rng );
		b[ i ] = rand_ab( rng );
		x[ i ] = rand_x( rng );

		// Ensure a,b > 0:
		if ( a[ i ] <= 0.0 ) {
			a[ i ] = 0.001;
		}
		if ( b[ i ] <= 0.0 ) {
			b[ i ] = 0.001;
		}
	}

	generate( x, a, b, len, name );
	free( x );
	free( a );
	free( b );
}

/**
* Generates "large range a,b" fixture (ibeta_large_data style).
*
* Following Boost's beta_data_generator: a = U[1,5]*10^k1,
* b = U[1,5]*10^k2, where k1,k2 are linearly spaced from -5 to 6 (11
* values each). For each (k1, k2) pair, 10 random x values in (0.0001, 1)
* are generated.
*
* Total: 11 * 11 * 10 = 1210 points.
*
* @param name  output filename
*/
void generate_large_range( const char *name ) {
	unsigned int nk = 11;
	unsigned int nx = 10;
	unsigned int len = nk * nk * nx;
	double *x;
	double *a;
	double *b;
	unsigned int idx;
	unsigned int ik1;
	unsigned int ik2;
	unsigned int ix;
	double k1;
	double k2;

	uniform_real_distribution<> rand_x( 0.0001, 1.0 );
	uniform_real_distribution<> rand_scale( 1.0, 5.0 );

	// Linearly spaced exponents from -5 to 6 (11 values):
	double exponents[ 11 ];
	linspace_f64( exponents, nk, -5.0, 6.0 );

	x = (double*) malloc( len * sizeof(double) );
	a = (double*) malloc( len * sizeof(double) );
	b = (double*) malloc( len * sizeof(double) );
	if ( x == NULL || a == NULL || b == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	idx = 0;
	for ( ik1 = 0; ik1 < nk; ik1++ ) {
		k1 = exponents[ ik1 ];
		for ( ik2 = 0; ik2 < nk; ik2++ ) {
			k2 = exponents[ ik2 ];
			for ( ix = 0; ix < nx; ix++ ) {
				a[ idx ] = rand_scale( rng ) * pow( 10.0, k1 );
				b[ idx ] = rand_scale( rng ) * pow( 10.0, k2 );
				x[ idx ] = rand_x( rng );
				idx++;
			}
		}
	}

	generate( x, a, b, len, name );
	free( x );
	free( a );
	free( b );
}

/**
* Generates "integer a,b" fixture (ibeta_int_data style).
*
* Following Boost's beta_data_generator_int: a,b from {1,5,9,...,37}
* (10 integer values, step 4), with 10 random x values in (0.0001, 1) for
* each (a, b) pair.
*
* Total: 10 * 10 * 10 = 1000 points.
*
* @param name  output filename
*/
void generate_int( const char *name ) {
	unsigned int na = 10;
	unsigned int nx = 10;
	unsigned int len = na * na * nx;
	double *x;
	double *a;
	double *b;
	unsigned int idx;
	unsigned int ia;
	unsigned int ib;
	unsigned int ix;

	int ab_vals[ 10 ] = { 1, 5, 9, 13, 17, 21, 25, 29, 33, 37 };

	uniform_real_distribution<> rand_x( 0.0001, 1.0 );

	x = (double*) malloc( len * sizeof(double) );
	a = (double*) malloc( len * sizeof(double) );
	b = (double*) malloc( len * sizeof(double) );
	if ( x == NULL || a == NULL || b == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	idx = 0;
	for ( ia = 0; ia < na; ia++ ) {
		for ( ib = 0; ib < na; ib++ ) {
			for ( ix = 0; ix < nx; ix++ ) {
				a[ idx ] = (double) ab_vals[ ia ];
				b[ idx ] = (double) ab_vals[ ib ];
				x[ idx ] = rand_x( rng );
				idx++;
			}
		}
	}

	generate( x, a, b, len, name );
	free( x );
	free( a );
	free( b );
}

/**
* Generates "large asymmetric" fixture (ibeta_large_asym_data style).
*
* Following Boost's beta_data_generator_asym: a,b are geometrically
* spaced from 0.1 to 50. For each (a,b) pair, x is placed near the
* distribution mean a/(a+b) by multiplying with factors that approach
* 1 from below and above. This stress-tests the crossover decision
* boundary where the code chooses between the direct and reflected
* incomplete beta formulas.
*
* Multipliers from Boost: {0.9, 0.99, 0.9999, 0.99999, 0.999999,
*   0.99999999, 1.001, 1.1, 1.00001, 1.0000001, 1.000000001}
*
* Total: 10 * 10 * 11 = 1100 points (minus invalid x >= 1).
*
* @param name  output filename
*/
void generate_large_asym( const char *name ) {
	unsigned int na = 10;
	unsigned int nmul = 11;
	unsigned int max_len;
	unsigned int idx;
	unsigned int i;
	unsigned int j;
	unsigned int k;
	double *x;
	double *a;
	double *b;
	double a_val;
	double b_val;
	double x0;
	double xv;

	// Geometrically spaced a,b from 0.1 to 50 (10 values):
	double ab_vals[ 10 ];
	for ( i = 0; i < na; i++ ) {
		ab_vals[ i ] = 0.1 * pow( 500.0, (double)i / (double)(na - 1) );
	}

	// Multipliers from Boost's beta_data_generator_asym:
	double muls[ 11 ] = {
		0.9, 0.99, 0.9999, 0.99999, 0.999999,
		0.99999999, 1.001, 1.1, 1.00001, 1.0000001,
		1.000000001
	};

	max_len = na * na * nmul;
	x = (double*) malloc( max_len * sizeof(double) );
	a = (double*) malloc( max_len * sizeof(double) );
	b = (double*) malloc( max_len * sizeof(double) );
	if ( x == NULL || a == NULL || b == NULL ) {
		printf( "Error allocating memory.\n" );
		exit( 1 );
	}

	idx = 0;
	for ( i = 0; i < na; i++ ) {
		for ( j = 0; j < na; j++ ) {
			a_val = ab_vals[ i ];
			b_val = ab_vals[ j ];
			x0 = a_val / ( a_val + b_val );
			for ( k = 0; k < nmul; k++ ) {
				xv = x0 * muls[ k ];
				if ( xv >= 1.0 || xv <= 0.0 ) {
					continue;
				}
				a[ idx ] = a_val;
				b[ idx ] = b_val;
				x[ idx ] = xv;
				idx++;
			}
		}
	}

	generate( x, a, b, idx, name );
	free( x );
	free( a );
	free( b );
}

/**
* Main execution sequence.
*/
int main( void ) {
	generate_small( "small_range.json" );

	generate_medium( "medium_range.json" );

	generate_large_range( "large_range.json" );

	generate_int( "int_values.json" );

	generate_large_asym( "large_asym.json" );

	return 0;
}
